#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

# Phase 8 (SPEC §13, §18): put values into the Secret Manager secrets that Terraform
# created (infra/terraform/secrets.tf). Values go to gcloud on stdin: never echoed,
# never in shell history, never in Terraform state. Safe to re-run: a secret that
# already has a value is skipped unless you choose to rotate it.
#
#   ./infra/bootstrap/dip-secrets.sh                      # dev (DIP_GCP_PROJECT_DEV)
#   DIP_SECRETS_PROJECT=<prod project> ./infra/bootstrap/dip-secrets.sh

cd "$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
PROJECT="${DIP_SECRETS_PROJECT:-$(_existing DIP_GCP_PROJECT_DEV || true)}"

TOTAL_STAGES=4

# _has_value NAME: true if the secret has an enabled version.
_has_value() {
  [[ -n "$(gcloud secrets versions list "$1" --project="$PROJECT" \
    --filter=state:ENABLED --limit=1 --format='value(name)' 2>/dev/null)" ]]
}

# _needs NAME: true if we should (re)write NAME; asks before replacing a value.
_needs() {
  if _has_value "$1"; then
    note "$1 already has a value."
    confirm "Rotate it (add a new version)?"
  fi
}

# _store NAME VALUE: add VALUE as the newest version of secret NAME, via stdin.
_store() {
  if printf '%s' "$2" | gcloud secrets versions add "$1" --project="$PROJECT" \
    --data-file=- >/dev/null; then
    printf '  %s✓ stored%s %s (new version) in %s\n' "$GREEN" "$RESET" "$1" "$PROJECT"
  else
    SKIPPED+=("Secret Manager secret $1")
    warn "could not store $1; is Terraform applied, and are you signed in to gcloud?"
  fi
}

banner "dip deploy secrets → $PROJECT"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check access"
[[ -n "$PROJECT" ]] || { warn "No project: set DIP_GCP_PROJECT_DEV in .env or DIP_SECRETS_PROJECT."; exit 1; }
say "Project: $PROJECT, as $(gcloud config get-value account 2>/dev/null)"
missing=()
for name in openai-api-key api-keys arize-otlp-headers; do
  gcloud secrets describe "$name" --project="$PROJECT" >/dev/null 2>&1 || missing+=("$name")
done
if (( ${#missing[@]} )); then
  warn "These secrets don't exist yet: ${missing[*]}"
  say "Apply Terraform first (docs/runbook.md, \"First deploy\"), then re-run this wizard."
  exit 1
fi
say "All three secrets exist. Next: their values."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "OpenAI API key (used by the worker)"
if _needs openai-api-key; then
  say "Recommended: a separate key for the deployed service, so you can revoke it or"
  say "cap its spend without touching your local key."
  open_url "https://platform.openai.com/api-keys"
  step "Create new secret key → name it 'dip-dev' → Create → copy it."
  step "Optional: Settings → Limits, set a monthly budget for the project."
  note "Or press Enter to reuse the key already in .env (DIP_OPENAI_API_KEY)."
  ask_secret DIP_OPENAI_API_KEY "Paste the key (input hidden):"
  if [[ "$DIP_OPENAI_API_KEY" == sk-* ]]; then
    _store openai-api-key "$DIP_OPENAI_API_KEY"
  else
    SKIPPED+=("openai-api-key: no key starting with sk- was given")
    warn "That doesn't look like an OpenAI key (sk-…); skipped."
  fi
  unset DIP_OPENAI_API_KEY
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "API key for the public API (X-API-Key)"
if _needs api-keys; then
  say "Generating a random key. It goes to Secret Manager, and to .env as DIP_API_KEY"
  say "so 'uv run dip submit' can call the deployed API."
  DIP_API_KEY=$(openssl rand -base64 32 | tr '+/' '-_' | tr -d '=\n')
  _store api-keys "$DIP_API_KEY"
  write_env DIP_API_KEY "$DIP_API_KEY"
  note "The API reads keys when an instance starts: new instances pick it up."
elif [[ -z "$(_existing DIP_API_KEY || true)" ]]; then
  say "The secret has a value but .env has no DIP_API_KEY. Copying it from Secret Manager."
  DIP_API_KEY=$(gcloud secrets versions access latest --secret=api-keys --project="$PROJECT" | cut -d, -f1)
  write_env DIP_API_KEY "$DIP_API_KEY"
fi
unset DIP_API_KEY
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Arize AX (production traces)"
if _needs arize-otlp-headers; then
  say "The worker exports one trace per job to Arize. Sign up or sign in (the free tier is enough)."
  open_url "https://app.arize.com"
  step "Space ID: open Settings for your space; it's listed there (it's also the part"
  step "  of the address bar after /spaces/). It looks like U3BhY2U6…"
  ask ARIZE_SPACE_ID "Paste the Space ID:"
  step "API key: Settings → Account Settings → Service Keys → + New Service Key."
  step "  Name 'dip-dev'. Under Organizations & Spaces add your space with role Member."
  step "  Create Service Key, then copy it now: it's shown only once."
  ask_secret ARIZE_API_KEY "Paste the service key (input hidden):"
  if [[ -n "$ARIZE_SPACE_ID" && -n "$ARIZE_API_KEY" ]]; then
    _store arize-otlp-headers "space_id=${ARIZE_SPACE_ID},api_key=${ARIZE_API_KEY}"
  else
    SKIPPED+=("arize-otlp-headers: Space ID or key was empty")
    warn "Missing a value; skipped. The worker needs this secret to start: re-run when ready."
  fi
  unset ARIZE_SPACE_ID ARIZE_API_KEY
fi
pause "Press Enter to finish"

finish
say "Next: tell Claude the secrets are in, or continue with docs/runbook.md, \"First deploy\"."
